import re

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_ISO = re.compile(
    rf"P(?:(?P<w>{_NUM})W)?(?:(?P<d>{_NUM})D)?"
    rf"(?:T(?:(?P<h>{_NUM})H)?(?:(?P<m>{_NUM})M)?(?:(?P<s>{_NUM})S)?)?"
)
_COMPONENT = re.compile(rf"\s*({_NUM})\s*([A-Za-z]+)\s*")


def _round(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare integer seconds.
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601.
    if s[:1] in ("P", "p"):
        m = _ISO.fullmatch(s.upper())
        if not m or s.upper() in ("P", "PT") or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        mult = {"w": 604800, "d": 86400, "h": 3600, "m": 60, "s": 1}
        total = sum(float(v) * mult[k] for k, v in m.groupdict().items() if v)
        return _round(total)

    # Clock notation.
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+(?:\.\d+)?", p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        nums = [float(p) for p in parts]
        if len(nums) == 2:
            nums.insert(0, 0.0)
        h, mi, se = nums
        return _round(h * 3600 + mi * 60 + se)

    # Number+unit components.
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

